<template><div class="page"><h2>用户与权限</h2><p>管理员创建用户账号并管理访问权限。</p><el-card><b>当前会话</b><span v-if="profile">{{profile.username}} · {{roleLabel(profile.role)}}</span><el-alert v-else title="未登录或会话已过期" type="warning" :closable="false"/></el-card><el-card v-if="profile?.role==='admin'"><template #header><b>创建用户账号</b></template><el-form inline><el-form-item label="用户ID"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password"/></el-form-item><el-form-item><el-button type="primary" @click="createUser">注册用户</el-button></el-form-item></el-form></el-card><el-card><template #header><b>角色权限目录</b></template><el-table :data="roles"><el-table-column prop="key" label="角色"><template #default="s">{{roleLabel(s.row.key)}}</template></el-table-column><el-table-column prop="permissions" label="权限"/></el-table></el-card></div></template>
<script setup>import{ref,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const profile=ref(null),roles=ref([]),form=ref({username:'',password:''}),roleLabel=r=>r==='admin'?'管理员':'用户';async function load(){try{profile.value=(await api.get('/permissions/profile/')).data;roles.value=(await api.get('/permissions/roles/')).data.roles}catch{profile.value=null}}async function createUser(){try{await api.post('/permissions/assign-role/',{username:form.value.username,password:form.value.password,role:'viewer'});ElMessage.success('用户账号创建成功');form.value={username:'',password:''}}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}onMounted(load)</script><style scoped>.page{padding:24px;max-width:1100px}.page h2{margin-bottom:8px}.page>p{color:#8391a5}.el-card{margin-bottom:16px}.el-card span{margin-left:18px}.el-tag{margin:3px}</style>
